/** One coloured Fluent glyph from [FluentColor]. */
@androidx.compose.runtime.Composable
fun FluentColorGlyph(key: String, tint: androidx.compose.ui.graphics.Color, size: androidx.compose.ui.unit.Dp, modifier: androidx.compose.ui.Modifier = androidx.compose.ui.Modifier) {
    val raw = FluentColor.map[key] ?: return
    val paths = androidx.compose.runtime.remember(key) { raw.map { androidx.compose.ui.graphics.vector.PathParser().parsePathString(it).toPath() } }
    val c = FluentColor.color(key) ?: tint
    androidx.compose.foundation.Canvas(modifier.then(androidx.compose.ui.Modifier.size(size))) {
        scale(this.size.width / 24f, pivot = androidx.compose.ui.geometry.Offset.Zero) { paths.forEach { drawPath(it, c) } }
    }
}
